def canConvertString(s, t, k):
    if len(s) != len(t):
        return False

    shifts_needed = [0] * 26

    for i in range(len(s)):
        diff = (ord(t[i]) - ord(s[i])) % 26
        if diff != 0:
            if shifts_needed[diff] * 26 + diff > k:
                return False
            shifts_needed[diff] += 1

    return True
